package net.spell_engine.api.spell;
import net.minecraft.util.Identifier; import net.spell_power.api.SpellSchool; import java.util.*; import org.jetbrains.annotations.Nullable;
public record SpellPool(List<Identifier> spellIds,List<SpellSchool> schools,boolean craftable){ public static final SpellPool empty=new SpellPool(List.of(),List.of(),true); @Nullable public SpellSchool firstSchool(){return schools.stream().findFirst().orElse(null);} public boolean isEmpty(){return spellIds.isEmpty();} public static class DataFormat{public List<String> spell_ids=List.of();public List<String> all_of_schools=List.of();public boolean creatable_as_spellbook=true;} public static class SyncFormat{public List<String> spell_ids=List.of();public List<String> schools=List.of();public boolean craftable;} }
